// Una fila por cliente activo; semana ISO + sufijo aleatorio (clave imposible de adivinar).
const c = $input.first().json;
const now = new Date();
const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
const day = (d.getUTCDay() + 6) % 7;
d.setUTCDate(d.getUTCDate() - day + 3);
const firstThu = new Date(Date.UTC(d.getUTCFullYear(), 0, 4));
const week = 1 + Math.round(((d.getTime() - firstThu.getTime()) / 86400000 - 3 + ((firstThu.getUTCDay() + 6) % 7)) / 7);
const weekStr = d.getUTCFullYear() + '-W' + String(week).padStart(2, '0');
const rand = Math.random().toString(36).slice(2, 10);
const r2key = 'reportes/' + c.client + '/' + weekStr + '-' + rand + '.html';
return [{ json: { client: c.client, week: weekStr, r2key: r2key, generatedAt: now.toISOString() } }];

// Render del snapshot — mantener sincronizado con src/reportes/builder.ts
// (summarizeDeals + buildReportHtml). Lee SOLO $input: producción llega vía
// 'Join data' y el test de integración vía 'Mock fixtures'.
function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
const d = $input.first().json;
const camps = Array.isArray(d.camps) ? d.camps : [];
const deals = Array.isArray(d.deals) ? d.deals : [];
let won = 0, revenue = 0;
for (const dl of deals) {
  const st = String(dl.Stage == null ? '' : dl.Stage).toLowerCase();
  if (/closed won|ganado/.test(st)) { won++; revenue += Number(dl.Amount || 0); }
}
const rows = camps.map(function(c) { return '      <li>' + esc(c.name) + ' — ' + esc(c.status) + '</li>'; }).join('\n');
const html = ['<!DOCTYPE html>', '<html lang="es">', '<head>', '<meta charset="utf-8">',
'<meta name="viewport" content="width=device-width, initial-scale=1">',
'<title>Reporte ' + esc(d.client) + ' — semana ' + esc(d.week) + '</title>',
'<style>',
'  body { font-family: system-ui, sans-serif; max-width: 720px; margin: 2rem auto; padding: 0 1rem; color: #1a1a1a; }',
'  .meta { color: #666; font-size: 0.85rem; }',
'  .kpis { display: flex; gap: 1rem; margin: 1.5rem 0; }',
'  .kpi { border: 1px solid #ddd; border-radius: 8px; padding: 1rem; flex: 1; }',
'  .kpi strong { display: block; font-size: 1.5rem; }',
'  #pdf-btn { padding: 0.6rem 1.2rem; font-size: 1rem; cursor: pointer; }',
'  @media print {',
'    #pdf-btn { display: none; }',
'    body { margin: 0; max-width: none; }',
'    .kpi { break-inside: avoid; }',
'  }',
'</style>', '</head>', '<body>',
'<h1>Reporte ' + esc(d.client) + '</h1>',
'<p class="meta">Semana ' + esc(d.week) + ' · generado ' + esc(d.generatedAt) + '</p>',
'<div class="kpis">',
'  <div class="kpi"><strong>' + camps.length + '</strong>Campañas</div>',
'  <div class="kpi"><strong>' + won + '</strong>Deals ganados</div>',
'  <div class="kpi"><strong>$' + revenue + '</strong>Revenue atribuido (last-touch 30d)</div>',
'</div>', '<h2>Campañas</h2>', '<ul>', rows, '</ul>',
'<p><button id="pdf-btn" onclick="window.print()">Descargar PDF</button></p>',
'</body>', '</html>'].join('\n');
return [{ json: { client: d.client || '', week: d.week || '', r2key: d.r2key || '', generatedAt: d.generatedAt || '', mock: d.mock || '', html: html, won: won, revenue: revenue, campaignCount: camps.length } }];

// Reune Build + subida: el nodo S3 devuelve solo {success} y Record necesita el contexto.
const idx = ($input.first().pairedItem && typeof $input.first().pairedItem.item === 'number') ? $input.first().pairedItem.item : 0;
const all = $('Build HTML').all();
const b = ((all[idx] || {}).json) || {};
return [{ json: { ...b, uploaded: $input.first().json } }];

// Junta cfg + Brevo + Zoho en un solo item: Build lee solo $input.
// (Brevo/Zoho reemplazan el item; sin esto el contexto se pierde.)
const _idx = ($input.first().pairedItem && typeof $input.first().pairedItem.item === 'number') ? $input.first().pairedItem.item : 0;
const _prep = $('Prep snapshot').all();
const cfg = (((_prep[_idx] || {}).json) || {});
const bitems = $('Brevo — campañas').all();
const zitems = $('Zoho — deals').all();
const camps = (((bitems[0] || {}).json || {}).campaigns) || [];
let deals = [];
for (const it of zitems) {
  const j = (it || {}).json || {};
  if (Array.isArray(j.data)) { deals = j.data; }
  else if (j.id && j.Deal_Name) { deals.push(j); }
}
return [{ json: { client: cfg.client || '', week: cfg.week || '', r2key: cfg.r2key || '', generatedAt: cfg.generatedAt || new Date().toISOString(), mock: '', camps: camps, deals: deals } }];

// Fixtures del test de integración: números conocidos para afirmar el cálculo.
// mock:'yes' desvía a 'Mock done' para no ensuciar reportes.snapshots.
// El objeto SÍ sube a R2 bajo mock/ y se borra al final del test.
return [{ json: {
  client: 'growbusy',
  week: '2999-W99',
  r2key: 'mock/integration-' + Math.random().toString(36).slice(2, 10) + '.html',
  generatedAt: new Date().toISOString(),
  mock: 'yes',
  camps: [
    { name: 'Promo <Flash> & "Sale"', status: 'sent' },
    { name: 'Winback', status: 'sent' },
    { name: 'Dormida', status: 'draft' }
  ],
  deals: [
    { Stage: 'Closed Won', Amount: 1000 },
    { Stage: 'Ganado', Amount: 500 },
    { Stage: 'Negotiation', Amount: 9999 },
    { Stage: 'Closed Lost', Amount: 250 }
  ]
} }];

